CREATE TYPE record_type_enum AS ENUM (
    'confirmed',
    'review',
    'synthetic'
);

CREATE TYPE use_case_category_enum AS ENUM (
    'LAW_ENFORCEMENT',
    'IMMIGRATION',
    'BENEFITS',
    'TRANSPORTATION',
    'INTERNAL',
    'HEALTH',
    'OTHER'
);

CREATE TYPE frt_category_enum AS ENUM (
    'facial_recognition',
    'possible_frt',
    'related_biometrics'
);

CREATE TYPE disclosure_pattern_enum AS ENUM (
    'AI_ONLY',
    'SORN_ONLY',
    'PRA_ONLY',
    'AI+SORN',
    'AI+PRA',
    'SORN+PRA',
    'All_three'
);

CREATE TYPE match_type_enum AS ENUM (
    'AI_SORN',
    'AI_PRA',
    'SORN_PRA',
    ''
);

CREATE TABLE frt_records (
    record_type record_type_enum NOT NULL,
    frt_instance_id TEXT,
    matching_name TEXT,
    canonical_agency TEXT,
    canonical_abbreviation TEXT,
    canonical_sub_agency TEXT,
    full_canonical_agency TEXT,
    use_case_category use_case_category_enum NOT NULL,
    frt_category frt_category_enum,
    matched_terms TEXT,
    disclosure_pattern disclosure_pattern_enum NOT NULL,
    in_ai_inventory BOOLEAN,
    in_sorns BOOLEAN,
    in_pra BOOLEAN,
    ai_description TEXT,
    sorn_description TEXT,
    pra_description TEXT,
    ai_inventory_url TEXT,
    sorn_federal_register_url TEXT,
    pra_reginfo_url TEXT,
    sorn_document_number TEXT,
    sorn_system_name TEXT,
    pra_icr_reference TEXT,
    pra_omb_control_number TEXT,
    review_id TEXT,
    match_type match_type_enum,
    is_confirmed_match BOOLEAN,
    reviewer_notes TEXT
);

CREATE INDEX idx_frt_records_frt_instance_id ON frt_records (frt_instance_id);
CREATE INDEX idx_frt_records_canonical_agency ON frt_records (canonical_agency);
CREATE INDEX idx_frt_records_use_case_category ON frt_records (use_case_category);
CREATE INDEX idx_frt_records_disclosure_pattern ON frt_records (disclosure_pattern);
CREATE INDEX idx_frt_records_record_type ON frt_records (record_type);

COPY frt_records FROM STDIN DELIMITER ',' CSV HEADER;
record_type,frt_instance_id,matching_name,canonical_agency,canonical_abbreviation,canonical_sub_agency,full_canonical_agency,use_case_category,frt_category,matched_terms,disclosure_pattern,in_ai_inventory,in_sorns,in_pra,ai_description,sorn_description,pra_description,ai_inventory_url,sorn_federal_register_url,pra_reginfo_url,sorn_document_number,sorn_system_name,pra_icr_reference,pra_omb_control_number,review_id,match_type,is_confirmed_match,reviewer_notes
confirmed,FRT-20260111-0101,,Department of Homeland Security,DHS,,DHS,INTERNAL,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"As part of the personnel security vetting process for continuous vetting-eligible employees, employees provide information and authorize access to information about themselves, including criminal history, credit reports, and other information. This information is collected and collated on an ongoing basis. UEAB presents aggregated information in a structured manner to help prioritize staffing.  Additionally, pursuant to and as authorized by Executive Order 13467, “Reforming Processes Related to Suitability for Government Employment, Fitness for Contractor Employees, and Eligibility for Access to Classified National Security Information,” employees must be enrolled in a continuous vetting program.     UEBA enhances the efficiency, accuracy, and effectiveness of personnel security processes by aggregating information provided by or authorized to be collected by an employee about the employee.     The AI output is the collated information is a risk matrix for human review. The AI output uses a hard coded scoring system to provide alerts for collated information that presents greater risk in the vetting process.  Staff reviews the risk matrix and uses the collated information in the matrix as background information for the personnel security vetting process. The collated information supports decisions about staffing priorities.",,,,,,,,,,,,,
confirmed,FRT-20260111-0137,,Department of Homeland Security,DHS,U.S. Citizenship and Immigration Services,DHS / USCIS,IMMIGRATION,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"The Verification Match Model utilizes machine learning (ML) to gather information from multiple systems and match it to known records by comparing names, dates of birth, and other identifiers. This supports two key USCIS Verification Division (VER) programs: the Employment Verification Program (E-Verify) and the Systematic Alien Verification for Entitlements (SAVE) Program.  The model streamlines verification data integration services by providing a ranked order of the best matches, expressed as confidence scores, between the identifiers used by the two programs. These improved matches increase the accuracy of E-Verify and SAVE, ensuring they use the most recent and accurate documents to determine benefit status. E-Verify handles approximately 250,000 requests per day and SAVE handles approximately 70,000 requests per day. Multiple data verification models for SAVE and E-Verify exist, complicating efficiency and performance. By consolidating these into a single, unified Verification Match Model within a separate microservice, the use case aims to improve the accuracy of responses and reduce the need for manual review. ML plays a key role in the continuous improvement of these models, ultimately reducing the need for manual case reviews.   Leveraging AI in the USCIS verification matching process of known records across systems is beneficial because it streamlines existing USCIS reviews by 1) improving system accuracy, 2) reducing human error through automated person-and-record match scoring, and 3) handling a higher volume of matches than traditional tools or manual processes can achieve.  The ouput is a recommendation and score indicating person-and-record match probability, used by verification systems (E-verify and SAVE) to improve accuracy in initial system responses.",,,,,,,,,,,,,
confirmed,FRT-20260111-0079,,Department of Homeland Security,DHS,U.S. Immigration and Customs Enforcement,DHS / ICE,LAW_ENFORCEMENT,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"ICE Enforcement Removal Operations’ Alternatives to Detention (ATD) program exists to ensure compliance with release conditions and provides important case management services for non-detained noncitizens. ATD consists of the Intensive Supervision Appearance Program (ISAP), which utilizes case management and technology tools to support noncitizens compliance with release conditions, court hearings, and final orders of removal, while allowing them to remain in their communities as they move through the immigration process or prepare for departure from the United States. Once individuals are in the ATD-ISAP program, officers periodically perform case reviews to determine if current levels of case management and technology assignment are appropriate for the noncitizen in the program or if they need to be adjusted. During the case review, the officer will consider numerous factors to include, but not limited to, current immigration status, supervision and compliance history, pending benefits, being a care giver or care provider, current immigration stage, pending criminal history and/or convictions, the hurricane score, and other factors. The factor known as the Hurricane Score is a quasi-binomial, binary classification machine learning (ML) model that is given information by an analyst that is known about an individual (factors from case management details and participant actions) and determines the probability that the individual will abscond based on absconding patterns the model has learned from inactive ATD-ISAP case data. The model returns a score from 1-5, with the higher number equating to a higher risk. The officer may use this score as one of the many factors previously described when deciding the appropriate level of case management and technology for noncitizens enrolled in the ATD-ISAP program. Because the hurricane score can quickly evaluate an enormous amount of information on thousands of noncitizens in the ATD-ISAP program, it provides officers with additional insight that they would not have otherwise had when performing a case review.",,,,,,,,,,,,,
confirmed,FRT-20260111-0057,,Department of Homeland Security,DHS,U.S. Immigration and Customs Enforcement,DHS / ICE,IMMIGRATION,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"The Student and Exchange Visitor Program (SEVP) uses AI to help policy analysts quickly find and summarize information about visa rules for students and schools, saving time and enabling faster responses to questions. SEVP is responsible for a wide variety of functions focusing on visa holders including F and M nonimmigrants and schools certified to admit them. The SEVP Regulation and Guidance Team performs research on large volumes of immigration policies, regulations, and other guidance for nonimmigrants to generate responses to data calls and queries from schools and students. Current methods for generating responses are manual and time-intensive. SEVP plans to leverage AI by developing a semantic search and LLM-based summarization tool using Retrieval Augmented Generation (RAG) to allow policy analysts to research and generate an initial analysis of applicable material more quickly and effectively. The generated output will be used as a starting point to assist policy analysts in completing their tasks, who will further refine, modify, vet, and review the response as part of their process. The source information provided to the tool is either in the public domain or is internal, non-sensitive data, with no Sensitive Personally Identifiable Information (SPII), Personally Identifiable Information (PII), nor Security Sensitive Information (SSI) used. This enhanced search capability will save hours of manual work per request, allowing analysts to respond more quickly with the most relevant information and focus on more complex policy and guidance issues.",,,,,,,,,,,,,
confirmed,FRT-20260111-0098,,Department of Homeland Security,DHS,U.S. Citizenship and Immigration Services,DHS / USCIS,IMMIGRATION,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"The Large Language Model (LLM) for Officer Training tool will use Generative AI (GenAI) to improve the way the agency trains immigration officer personnel. The tool will generate dynamic, personalized training materials that adapt to officers’ specific needs and ensure the best possible knowledge and training on a wide range of current policies and laws relevant to their jobs. The goal is to enhance trainees’ understanding and retention of crucial information, increase the accuracy of their decision-making process, and limit the need for retraining over time. The AI outputs human-like conversation in a text format, like other AI chatbots, but is specially trained and tuned for Refugee, Asylum, and International Operations (RAIO) Officer training.",,,,,,,,,,,,,
confirmed,FRT-20260111-0030,,Department of Homeland Security,DHS,U.S. Customs and Border Protection,DHS / CBP,IMMIGRATION,facial_recognition,face recognition; face capture; biometric; TVS; Traveler Verification Service,AI_ONLY,True,False,False,"The Traveler Verification Service (TVS) provides CBP a biometric entry/exit system to record arrivals and departures to and from the United States. CBP uses TVS as its backend matching service for all biometric entry and exit operations that use Facial Comparison. CBP creates localized photo ""galleries"" from images captured during previous entry inspections, photographs from U.S. passports and U.S. visas, and photographs from other DHS encounters. The images are converted into templates and the actual photograph is discarded. The templates are securely stored, and are what make up the TVS gallery. The templates are then used by the Facial Comparison system to verify a traveler's identity when they arrive or depart the U.S. When the traveler presents him or herself for entry, or for exit, the traveler will encounter a camera connected to TVS. This camera matches live images with the existing photo templates from passenger travel documents. Once the camera captures a quality image and the system successfully matches it with historical photo templates of all travelers from the gallery associated with that particular manifest, the traveler proceeds to inspection for admissibility by a CBP Officer, or exits the United States. For more information, please read the DHS/CBP/PIA-056 - Privacy Impact Assessment for the Traveler Verification Service.",,,,,,,,,,,,,
confirmed,FRT-20260111-0105,,Department of Homeland Security,DHS,Transportation Security Administration,DHS / TSA,TRANSPORTATION,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"TSA uses Low Probability of False Alarm (Low-PFA) algorithms to train AI systems deployed for on-person screening.  It utilizes ML to improve detection performance while decreasing alarm rates and passengers touch rates. The algorithm is gender agnostic, no longer requiring officers to select a passenger’s gender prior to being scanned. AIT scanner throughput and utilization have increased with this new algorithm. Once the algorithm is trained, it is locked down and no longer learning.",,,,,,,,,,,,,
confirmed,FRT-20260111-0083,,Department of Homeland Security,DHS,U.S. Immigration and Customs Enforcement,DHS / ICE,IMMIGRATION,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"The Information Assurance Division (IAD) within ICE is responsible for providing internal Cybersecurity Services to ICE. Within IAD is the Cyber Defense & Intelligence (CD&I) Branch whose mission is operating the ICE Security Operations and Computer Security Incident Response Center. The Branch performs information assurance mitigation, responds to and reports on Information Technology (IT) security incidents, performs systems vulnerability testing, and monitors and evaluates the security performance on sensitive enterprise systems. The CD&I Branch performs monitoring and analysis on aggregate ICE cybersecurity data to identify and respond to anomalous and malicious activity. This data is limited to IT security operations and is not used to conduct AI-enabled workplace surveillance or automated personnel management. CD&I uses several AI-enabled cybersecurity tools to analyze this data. Machine learning (ML) models, such as classification and regression models, are used to analyze historical data and detect emerging threats through pattern recognition. Additional capabilities include the identification of real-time threats by using algorithms and ML from a vast database of known threats and patterns during continuous monitoring of ICE cybersecurity data. This includes recognizing phishing patterns, malware signatures, or abnormal network traffic patterns across a variety of tools. This provides security analysts with modern tools to identify and respond to threats much more quickly than previously possible, minimizing potential damage to systems and data.",,,,,,,,,,,,,
confirmed,FRT-20260111-0163,,General Services Administration,GSA,,GSA,OTHER,possible_frt,facial matching,AI_ONLY,True,False,False,,,,,,,,,,,,,,
confirmed,FRT-20260111-0109,,Department of Homeland Security,DHS,Transportation Security Administration,DHS / TSA,OTHER,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"TSA's Training and Development office is using an off-the-shelf, on-demand, employee learning/training platform which contains commercial training on many topics tailored to each user's interests and skill level to support their personalized training plans and goals. One available component of the platform uses a large language model (LLM) as part of an interactive, dialogue-style training functionality to communicate with and advise the learner to develop critical non-security sensitive soft skills such as customer service and communicating on difficult topics using this conversation simulation tool. This function, if enabled, is intended to augment, and not replace, professional training interventions and human interaction.",,,,,,,,,,,,,
confirmed,FRT-20260111-0020,,Department of Homeland Security,DHS,Federal Emergency Management Agency,DHS / FEMA,OTHER,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"The Response Geospatial Office (RGO) is exploring the use of AI to assist in the prioritization of structural and debris assessments. RGO reviews satellite, aerial, and radar imagery to expedite damage assessments in the aftermath of a disaster. RGO is utilizing several AI techniques, including computer vision, machine learning, and deep learning, to help prioritize imagery exploitation by identifying areas likely having damage or debris. Areas indicated as likely having damage or debris are prioritized for imagery exploitation by analysts, reducing the time required for visual damage assessments. FEMA will integrate these automated tools for imagery-based damage assessments into RGO processes and systems to inform FEMA geospatial analysts. FEMA geospatial analysts will review output and develop recommendations, so FEMA can quickly detect and characterize damaged and undamaged buildings, identify concentrations of damage, detect debris, and support rapid response and recovery activities. AI models generate points or polygons over areas where damage or debris is likely. This output is a recommendation meant to trigger investigation by human analysts via traditional damage assessments. In large-scale incidents, imagery collection can be comprised of hundreds of thousands of miles of land and millions of structures. AI automation allows for the prioritization of imagery exploitation where damage is likely to have occurred, reducing the time required to identify impacts and summarize damage sustained.",,,,,,,,,,,,,
confirmed,FRT-20260111-0043,,Department of Homeland Security,DHS,U.S. Customs and Border Protection,DHS / CBP,LAW_ENFORCEMENT,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"Advanced Analytics for X-ray Images (AAXI) aims to address the problem of anomaly detection in empty commercial vehicles entering the U.S. at land border ports of entry. The AI models achieve this goal by encoding past x-ray images of vehicular border crossings in a semantically meaningful way and comparing the current crossing to detect differences amongst the images to identify anomalies. The system produces bounding boxes around an anomaly or unidentifiable object(s) within an image or any portion of the image that cannot be identified or explained. Benefits include enhancement of the capability of humans to consistently detect items of interest/concern present (and possibly concealed) in vehicles crossing into the United States, and increased clearance rate at border crossings so that vehicles operating safely and lawfully may pass through the border faster.",,,,,,,,,,,,,
confirmed,FRT-20260111-0016,,Department of Homeland Security,DHS,,DHS,INTERNAL,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"DHS employees are permitted to use commercially available generative AI for text generation in day-to-day work. Commonly referred to as AI chatbots, these tools can dynamically create written content through text prompts submitted by the user. They use Natural Language Processing (NLP) and Large Language Models (LLM) to produce natural sounding language in a wide variety of contexts and styles. Approved applications of commercial generative AI tools for DHS business include generating first drafts of documents that a human would subsequently review, conducting and synthesizing research on open-source information, and developing briefing materials or preparing for meetings and events.",,,,,,,,,,,,,
confirmed,FRT-20260111-0068,,Department of Homeland Security,DHS,U.S. Customs and Border Protection,DHS / CBP,LAW_ENFORCEMENT,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"CBP uses software to analyze field imaging in monitored areas and to provide alerts when it detects the presence of an Item of Interest (IoI) that the AI model was trained to detect (i.e., persons, vehicles, animals) in the image frame. The software outputs include a superimposed outline surrounding of the IoI within the image or live feed. Each outline is color-coded based on the degree of certainty that the detection is the item it was trained to detect. The software allows the user to filter based on preferences for detections of IoI. This filtering allows for quick and efficient review and adjudication of the detection(s). After the alert of a detection, a trained CBP agent or user, reviews the image to identify and classify the activity taking place.",,,,,,,,,,,,,
confirmed,FRT-20260111-0025,,Department of Homeland Security,DHS,Federal Emergency Management Agency,DHS / FEMA,INTERNAL,possible_frt,face recognition; face capture,AI_ONLY,True,False,False,"FEMA Office of the Chief Financial Officer Generative Pre-trained Transformer (OCFO GPT), Travel Policy GPT and Fiscal Policy GPT are internal Generative AI (GenAI) tools designed to support the FEMA workforce by generating initial responses to various queries. These tools leverage relevant public and internal documents to draft preliminary responses, which are then refined prior to formal submission. They assist in the data gathering stage, but do not replace the critical review and judgement of FEMA analysts and leadership.  FEMA OCFO GPT generates initial responses to questions for the record, leveraging public and internal documents, and provides a preliminary response to the Program Office to use in their formal response to the request. It reduces the data gathering stage, saving analysts 80% of the initial effort.  Travel Policy GPT generates initial responses to questions regarding FEMA/DHS Travel Policy, including the JTR, and provides a preliminary response to the travel specialist to use in their formal response to the queries.  It improves response times, saving users 80-90% of the time compared to regular engagement with the Travel Service Center.  Fiscal Policy GPT provides preliminary responses to questions regarding FEMA/DHS Fiscal Policy and will generate a draft response with references to assist FEMA internal workforce in compliance with established policy.  It saves users 80-90% of the time compared to regular engagement with DHS /FEMA OCFO policy and speeds up resolution times.  These tools do not replace analysts’ work or leadership review, but enhance efficiency in data gathering and preliminary response stages.",,,,,,,,,,,,,
confirmed,FRT-20260111-0384,"Records are collected for the purpose of furthering S&T's mission to push innovation and development, and the use of high technology in support of homeland security. The purposes of the records are to",Department of Homeland Security,DHS,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; Science & Technology Directorate-001 Research, Development, Test, and Evaluation Records System of Records Records are collected for the purpose of furthering S&T's mission to push innovation and development, and the use of high technology in support of homeland security. The purposes of the records are to: â¢ Understand the motivations and behaviors of terrorists, individuals that engage in violent or criminal activities, terrorist groups, and groups that engage in violent or criminal activities. â¢ Understand terrorist incidents and the phenomenon of terrorism and identify trends and patterns in terrorist activities. â¢ Collect and maintain searchable records of individuals (such as subject matter experts on chemical weapons) and/or their characteristics and professional accomplishments, organized according to categories useful for the purpose of collaboration or conduct of research, including research to determine the efficacy and utility of new or enhanced technologies intended for eventual transition to and use by S&T's customers. â¢ Evaluate the performance and utility to the futu S&T RDT&E Records will vary according to the specific project. The information may include, but is not limited to, an individual's:",,,https://www.federalregister.gov/documents/full_text/xml/2013-00602.xml,,2013-00602,"Privacy Act of 1974; Science & Technology Directorate-001 Research, Development, Test, and Evaluation Records System of Records",,,,,,
confirmed,FRT-20260111-0233,"A. To manage the Military Service workforce, and its operational readiness and assigned mission goals. B. To support Department and Component force and manning requirements ( i.e., size and compositio",Department of Defense,DOD,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; System of Records A. To manage the Military Service workforce, and its operational readiness and assigned mission goals. B. To support Department and Component force and manning requirements ( i.e., size and composition of the force) and organizational structure ( i.e., distribution of the force) to meet operational and logistics readiness needs. C. To document, manage, track, carry out, and oversee a variety of personnel and human resource actions concerning Military Service members, such as promotions; determining status, eligibility, and Service member rights and benefits; and computing length of service. D. To serve as the basic source of factual data (for example: duty titles, duty locations, performance reports, promotion determinations, administrative actions, etc.) about an individual's Military Service from entrance through separation or retirement. E. To give legal force and effect to personnel and human resources transactions and establish rights and benefits under pertinent laws and regulati The information required to be maintained in standard military human resource records is defined by DoD policy and any pertinent Service-specific regulations. The records include military human resource information and/or data related to a Service member's career. The specific contents of a Service member's records will vary based on the events of their career. The type of information generally maintained in the military human resources records include the following:",,,https://www.federalregister.gov/documents/full_text/xml/2024-09967.xml,,2024-09967,Privacy Act of 1974; System of Records,,,,,,
confirmed,FRT-20260111-0176,The purpose of the TSA Preâ TM Application Program is to: (a) perform security threat assessments and to identify individuals who are a low risk to transportation or national security and are theref,Department of Homeland Security,DHS,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; Department of Homeland Security/Transportation Security AdministrationâDHS/TSA-021 TSA Preâ TM Application Program System of Records The purpose of the TSA Preâ TM Application Program is to: (a) perform security threat assessments and to identify individuals who are a low risk to transportation or national security and are therefore eligible to receive expedited security screening; (b) assist in the management and tracking of the status of security threat assessments of individuals who apply to the TSA Preâ TM Application Program; (c) permit the retrieval of the results of security threat assessments, including criminal history records checks and searches in other governmental data systems, performed on the individuals covered by this system; (d) permit the retrieval of information from other terrorist-related, law enforcement, immigration, and intelligence databases on the individuals covered by this system; and (e) track the fees incurred, and payment of those fees, when appropriate, for services related to security threat assessments. In addition to those disclosures generally permitted under 5 U.S.C. 552a(b) This system may contain any, or all, of the following information regarding individuals covered by this system:",,,https://www.federalregister.gov/documents/full_text/xml/2013-21979.xml,,2013-21979,Privacy Act of 1974; Department of Homeland Security/Transportation Security AdministrationâDHS/TSA-021 TSA Preâ TM Application Program System of Records,,,,,,
confirmed,FRT-20260111-0360,The purpose of the Insider Threat Program system of records is to manage insider threat matters; facilitate insider threat investigations and activities associated with counterintelligence and counter,Department of Homeland Security,DHS,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act; Department of Homeland Security/ALL-038 Insider Threat Program System of Records The purpose of the Insider Threat Program system of records is to manage insider threat matters; facilitate insider threat investigations and activities associated with counterintelligence and counterespionage complaints, inquiries, and investigations; identify threats to DHS resources and information assets; track referrals of potential insider threats to internal and external partners; and provide statistical reports and meet other insider threat reporting requirements. In addition to those disclosures generally permitted under 5 U.S.C. 552a(b) of the Privacy Act, all or a portion of the records or information contained in this system may be disclosed outside DHS as a routine use pursuant to 5 U.S.C. 552a(b)(3) as follows: A. To the Department of Justice (DOJ), including Offices of the U.S. Attorneys, or other federal agency conducting litigation or in proceedings before any court, adjudicative, or administrative body, when it is relevant or necessary to the litigation and one of the Categories of Records in the system include:",,,https://www.federalregister.gov/documents/full_text/xml/2016-03924.xml,,2016-03924,Privacy Act; Department of Homeland Security/ALL-038 Insider Threat Program System of Records,,,,,,
confirmed,FRT-20260111-0182,"Established in 1967, the NCIC is a national criminal justice information system linking criminal (and authorized non-criminal) justice agencies located in the 50 states, the District of Columbia, U.S.",Department of Justice,DOJ,,,LAW_ENFORCEMENT,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; System of Records Established in 1967, the NCIC is a national criminal justice information system linking criminal (and authorized non-criminal) justice agencies located in the 50 states, the District of Columbia, U.S. territories and possessions, as well as selected foreign countries, to facilitate the cooperative sharing of criminal justice information. The NCIC provides a system to receive and maintain information contributed by participating agencies relating to criminal justice and national security missions. Information maintained in the NCIC is readily accessible for authorized purposes by authorized users via text-based queries ( i.e., using names and other descriptive data). The purposes of maintaining records in the NCIC include combatting acts of terrorism; apprehending fugitives; solving crimes; locating missing persons; locating and returning stolen property; protecting individuals during declared emergency situations; protecting victims of domestic violence; monitoring registered sex offen The NCIC may contain records about individuals described by the categories listed above. Records may include all manner of identifying information, such as name, Social Security number, date of birth, place of birth, physical description, photograph, descriptive information about fingerprints and other biometrics which may be available (the biometrics themselves and not maintained within the NCIC), passport and/or driver's license information, personal and business addresses and telephone numbers, and other personal identifiers. Records in the system may include details pertinent to particular file types, such as law enforcement information, visa/immigration information, and terrorism information; information relevant to the protection of health, safety, or property; physical or medical characteristics or other personal information deemed necessary to identify an individual, protect law enforcement officers, and identify and protect law enforcement subjects; and information relevant to",,,https://www.federalregister.gov/documents/full_text/xml/2019-19449.xml,,2019-19449,Privacy Act of 1974; System of Records,,,,,,
confirmed,FRT-20260111-0366,"The purpose of the FBI's Online Collaboration Systems is to facilitate and support internal and external collaboration for and among the FBI, federal, state, local, tribal, territorial, foreign, and i",Department of Justice,DOJ,,,LAW_ENFORCEMENT,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; System of Records The purpose of the FBI's Online Collaboration Systems is to facilitate and support internal and external collaboration for and among the FBI, federal, state, local, tribal, territorial, foreign, and international criminal justice agencies, emergency management personnel and first responders, private sector entities, and United States military and other government personnel involved in criminal justice and national security matters in the United States and approved countries worldwide. Expanding the available collaboration tools of the FBI and its partners enables the FBI to carry out its national security and criminal justice missions by providing a real-time online environment for criminal justice agencies, the FBI, and its partners to exchange information internally and externally. Records may include biographical information about individuals who are employees, contractors, detailees, assignees, or interns of the FBI, criminal justice agencies, or other FBI partners as outlined above who are authorized to access an FBI online collaboration system. Biographical information may include name, phone number, email address, organization, photographs, citizenship, designation as a law enforcement officer with arresting powers, user login identification, and other information users choose to share within the collaboration system.",,,https://www.federalregister.gov/documents/full_text/xml/2017-25994.xml,,2017-25994,Privacy Act of 1974; System of Records,,,,,,
confirmed,FRT-20260111-0192,Privacy Act of 1974; System of Records,,,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,Privacy Act of 1974; System of Records,,,https://www.federalregister.gov/documents/full_text/xml/2012-2505.xml,,2012-2505,Privacy Act of 1974; System of Records,,,,,,
confirmed,FRT-20260111-0362,"The purpose of this system is to serve as the primary repository for tracking entry and exit data throughout the immigrant and non-immigrant pre-entry, entry, status management, and exit processes. Th",Department of Homeland Security,DHS,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; Department of Homeland Security/U.S. Customs and Border Protectionâ021 Arrival and Departure Information System The purpose of this system is to serve as the primary repository for tracking entry and exit data throughout the immigrant and non-immigrant pre-entry, entry, status management, and exit processes. This data is collected by DHS or other federal or foreign government agencies and is used in connection with DHS missions such as national security, law enforcement, immigration, intelligence, and other DHS mission-related functions. Data is also used to provide associated testing, training, management reporting, planning and analysis, or other administrative purposes. Similar data may be collected from multiple sources to verify or supplement existing data and to ensure a high degree of data accuracy. Specifically, DHS/CBP uses ADIS data to: (1) Identify lawfully admitted non-immigrants who remain in the United States beyond their period of authorized stay (which may have a bearing on an individual's right or authority to remain in the country, ability to receive or renew a U.S. visa, or to Information contained in this system of records includes, but is not limited to:",,,https://www.federalregister.gov/documents/full_text/xml/2015-29445.xml,,2015-29445,Privacy Act of 1974; Department of Homeland Security/U.S. Customs and Border Protectionâ021 Arrival and Departure Information System,,,,,,
confirmed,FRT-20260111-0321,"The purpose of this system is to support DHS/OIS in fulfilling its mandate to regularly prepare an extensive series of analytical and statistical reports on border security, immigration enforcement ac",Department of Homeland Security,DHS,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; System of Records The purpose of this system is to support DHS/OIS in fulfilling its mandate to regularly prepare an extensive series of analytical and statistical reports on border security, immigration enforcement activities, refugee and asylum claims, and other immigration requests and events. â¢ Alien Registration Number(s) (A-Number);",,,https://www.federalregister.gov/documents/full_text/xml/2020-04978.xml,,2020-04978,Privacy Act of 1974; System of Records,,,,,,
confirmed,FRT-20260111-0293,"Delete entry and replace with âIn addition to those disclosures generally permitted under 5 U.S.C. 552a(b) of the Privacy Act of 1974, as amended, the records contained herein may specifically be di",Department of Defense,DOD,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; System of Records Delete entry and replace with âIn addition to those disclosures generally permitted under 5 U.S.C. 552a(b) of the Privacy Act of 1974, as amended, the records contained herein may specifically be disclosed outside the DoD as a routine use pursuant to 5 U.S.C. 552a(b)(3) as follows: Delete entry and replace with âInformation on individuals identified in the IMESA Interoperability Layer Service (IoLS) DoD Population Database: DoD ID number, Social Security Number (SSN), last name, date of birth, credential type, issuance, and expiration information; and security alert information (alert type, alert source, case number).",,,https://www.federalregister.gov/documents/full_text/xml/2015-31867.xml,,2015-31867,Privacy Act of 1974; System of Records,,,,,,
confirmed,FRT-20260111-0385,"1. To provide services related to identity and document verification services. 2. To issue and manage public key certificates, user registration, email addresses, and/or electronic postmarks. 3. To pr",U.S. Postal Service,USPS,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; System of Records 1. To provide services related to identity and document verification services. 2. To issue and manage public key certificates, user registration, email addresses, and/or electronic postmarks. 3. To provide secure mailing services. 4. To protect business and personal communications. 5. To enhance personal identity and privacy protections. 6. To improve the customer experience and facilitate the provision of accurate and reliable delivery information. 7. To identify, prevent, or mitigate the effects of fraudulent transactions. 8. To support other Federal Government Agencies by providing authorized services. 9. To ensure the quality and integrity of records. 10. To enhance the customer experience by improving the security of Change of Address (COA) and Hold Mail processes. 11. To protect USPS customers from becoming potential victims of mail fraud and identity theft. 12. To identify and mitigate potential fraud in the COA and Hold Mail processes. 13. To verify a customer's identity when a 1. Customer information: Name, address, customer ID(s), telephone number, text message number and carrier, mail and email address, date of birth, place of birth, company name, title, role, and employment status.",,,https://www.federalregister.gov/documents/full_text/xml/2018-26428.xml,,2018-26428,Privacy Act of 1974; System of Records,,,,,,
confirmed,FRT-20260111-0186,"The purpose of the collection is to screen passengers and crew arriving in, transiting through, and departing from (and in the case of crew, overflying) the United States to identify those passengers ",Department of Homeland Security,DHS,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; Department of Homeland Security/United States Customs and Border Protection Advanced Passenger Information System Systems of Records The purpose of the collection is to screen passengers and crew arriving in, transiting through, and departing from (and in the case of crew, overflying) the United States to identify those passengers and crew who may pose a risk to border, aviation, vessel, rail, bus, or public security, may be a terrorist or suspected terrorist or affiliated with or suspected of being affiliated with terrorists, may be inadmissible, may be a person of interest, or may otherwise be engaged in activity in violation of U.S. law, or the subject of wants or warrants. APIS allows CBP to more effectively and efficiently facilitate the entry of legitimate travelers into the United States and the departure of legitimate travelers from the United States. As travelers prepare to depart for or from the United States, DHS officers, using APIS, can quickly cross-reference the results of the advanced research that has been conducted through CBP's law enforcement databases, as well as using information from the TSDB, The records in the database include the following information:",,,https://www.federalregister.gov/documents/full_text/xml/2015-05798.xml,,2015-05798,Privacy Act of 1974; Department of Homeland Security/United States Customs and Border Protection Advanced Passenger Information System Systems of Records,,,,,,
confirmed,FRT-20260111-0263,Privacy Act of 1974; Department of Homeland Security Immigration and Customs Enforcement-007 Alien Criminal Response Information Management System of Records,Department of Homeland Security,DHS,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,,,,https://www.federalregister.gov/documents/full_text/xml/2010-3605.xml,,2010-3605,,,,,,,
confirmed,FRT-20260111-0344,"The primary purposes of the system are: To ensure the safety and security of Federal facilities, systems, or information, and of facility occupants and users; to provide for interoperability and trust",General Services Administration,GSA,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; Notice of an Updated System of Records The primary purposes of the system are: To ensure the safety and security of Federal facilities, systems, or information, and of facility occupants and users; to provide for interoperability and trust in allowing physical access to individuals entering Federal facilities; and to allow logical access to Federal information systems, networks, and resources on a government-wide basis. In addition to those disclosures generally permitted under 5 U.S.C. Section 552a(b) of the Privacy Act, all or a portion of the records or information contained in this system may be disclosed outside GSA as a routine use pursuant to 5 U.S.C. 552a(b)(3) as follows: a. To the Department of Justice (DOJ) when: (1) The agency or any component thereof; or (2) any employee of the agency in his or her official capacity; (3) any employee of the agency in his or her individual capacity where agency or the Department of Justice has agreed to represent the employee; or (4) the United States Government is a party to li Enrollment records maintained in the PIV IDMS on individuals applying for the PIV program and a PIV credential through the GSA HSPD-12 managed service include the following data fields: Full name; Social Security Number; Applicant ID number, date of birth; current address; digital color photograph; fingerprints; biometric template (two fingerprints); organization/office of assignment; employee affiliation; work email address; work telephone number(s); office address; copies of identity source documents; employee status; military status; foreign national status; federal emergency response official status; law enforcement official status; results of background check; Government agency code; and PIV card issuance location. Records in the PIV IDMS needed for credential management for enrolled individuals in the PIV program include: PIV card serial number; digital certificate(s) serial number; PIV card issuance and expiration dates; PIV card PIN; Cardholder Unique Identifier (CHUID); and ca",,,https://www.federalregister.gov/documents/full_text/xml/2015-26940.xml,,2015-26940,Privacy Act of 1974; Notice of an Updated System of Records,,,,,,
confirmed,FRT-20260111-0390,"The purpose of this system is to enhance DHS's ability to: Identify, apprehend, and/or prosecute individuals who pose a potential law enforcement or security risk; aid in the enforcement of the custom",Department of Homeland Security,DHS,,,OTHER,facial_recognition,biometric,SORN_ONLY,False,True,False,,"Privacy Act of 1974; Department of Homeland Security, U.S. Customs and Border Protection, DHS/CBPâ017 Analytical Framework for Intelligence (AFI) System of Records The purpose of this system is to enhance DHS's ability to: Identify, apprehend, and/or prosecute individuals who pose a potential law enforcement or security risk; aid in the enforcement of the customs and immigration laws, and other laws enforced by DHS at the border; and enhance United States security. AFI uses data to: (1) Identify individuals, associations, or relationships that may pose a potential law enforcement or security risk, target cargo that may present a threat, and assist intelligence product users in the field in preventing the illegal entry of people and goods, or identifying other violations of law; (2) Allow analysts to conduct additional research on persons and/or cargo to understand whether there are patterns or trends that could identify potential law enforcement or security risks; and (3) Allow finished intelligence product users with a need to know to query or receive relevant finished intelligence products. Source data are to be handled consistent with the publ AFI uses information from a variety of federal and commercial systems. If additional data is ingested and that additional data does not require amendment of the categories of records in this SORN, the PIA for AFI will be updated to reflect that information. The updated PIA can be found at www.dhs.gov/privacy. Information from such source systems is incorporated into AFI's five general categories of records:",,,https://www.federalregister.gov/documents/full_text/xml/2012-13813.xml,,2012-13813,"Privacy Act of 1974; Department of Homeland Security, U.S. Customs and Border Protection, DHS/CBPâ017 Analytical Framework for Intelligence (AFI) System of Records",,,,,,
